// Package adminui embeds the admin SPA build output (admin/dist is
// generated by `pnpm -C admin build` → ../server/adminui/dist).
// Serves it at /admin/ with SPA index.html fallback.
//
// adminui 内嵌管理后台构建产物，挂在 /admin/，SPA 路径回退到 index.html。
package adminui

import (
	"bytes"
	"embed"
	"io/fs"
	"net/http"
	"strings"
	"time"
)

//go:embed all:dist
var dist embed.FS

// Handler serves the embedded SPA; unknown paths fall back to index.html.
func Handler() http.Handler {
	sub, err := fs.Sub(dist, "dist")
	if err != nil {
		return http.NotFoundHandler()
	}
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := strings.TrimPrefix(r.URL.Path, "/admin/")
		if p == "" || p == "/" {
			p = "index.html"
		}
		if _, err := fs.Stat(sub, p); err != nil {
			p = "index.html" // SPA fallback / 单页应用路径回退
		}
		data, err := fs.ReadFile(sub, p)
		if err != nil {
			http.NotFound(w, r)
			return
		}
		http.ServeContent(w, r, p, time.Now(), bytes.NewReader(data))
	})
}
